using System.IO;
using System.Text.Json;
using VisionCore;
using VisionPlugins.Calibration;
public static class NImageOutputMetricsChecks{
 public static int Run(){int checks=0;var failures=new List<string>();var fileMatrixComparisons=new List<object>();var translationOriginComparisons=new List<object>();void Check(bool pass,string message){checks++;if(!pass)failures.Add(message);}
  using var evidence=JsonDocument.Parse(File.ReadAllText("docs/plugins/n-image-numerical-evidence.json"));var root=evidence.RootElement;var pairs=root.GetProperty("pairs").EnumerateArray().ToArray();var translations=root.GetProperty("translationCases").EnumerateArray().ToArray();var originalTranslation=translations.Single(r=>r.GetProperty("rot").GetInt32()==0);var reports=new List<object>();
  foreach(var native in root.GetProperty("batches").EnumerateArray().Concat(translations)){
   int trans=native.GetProperty("trans").GetInt32(),rot=native.GetProperty("rot").GetInt32();var boards=new List<NImageDetectedBoard>();var frames=new List<NImageFrame>();var image=new GrayImage(1,1,new byte[1]);
   for(int i=0;i<trans;i++){boards.Add(new(10,originalTranslation.GetProperty("corners").EnumerateArray().Select(c=>new NImageBoardPoint(c.GetProperty("world")[0].GetInt32(),c.GetProperty("world")[1].GetInt32(),c.GetProperty("pixels")[i][0].GetDouble(),c.GetProperty("pixels")[i][1].GetDouble())).ToArray(),[]));frames.Add(new(image,1,i%3,i/3,0));}
   if(rot>0){var points=Enumerable.Range(0,rot).Select(_=>new Dictionary<(int,int),NImageBoardPoint>()).ToArray();for(int i=0;i<rot-1;i++)foreach(var c in pairs[i].GetProperty("corners").EnumerateArray())for(int side=0;side<2;side++){int x=c.GetProperty("world")[0].GetInt32(),y=c.GetProperty("world")[1].GetInt32();var p=c.GetProperty("pixels")[side];points[i+side][(x,y)]=new(x,y,p[0].GetDouble(),p[1].GetDouble());}for(int i=0;i<rot;i++){boards.Add(new(10,points[i].Values.OrderBy(v=>v.IndexY).ThenBy(v=>v.IndexX).ToArray(),[]));frames.Add(new(image,2,0,0,i*10));}}
   var solved=NImageBatchSolver.Solve(new(new(frames,frames.Count,frames.Count),0,boards));Check(solved.Complete,"Numerical batch complete");var metrics=NImageOutputMetrics.Measure(solved,frames.Where(f=>f.Kind==1).Select(f=>new NImagePose(f.PhysicalX,f.PhysicalY,f.Angle)).ToArray(),frames.Where(f=>f.Kind==2).Select(f=>new NImagePose(f.PhysicalX,f.PhysicalY,f.Angle)).ToArray());
   if(trans==9&&rot==3){using var fileEvidence=JsonDocument.Parse(File.ReadAllText("docs/plugins/n-image-three-rotation-file-evidence.json"));foreach(var record in fileEvidence.RootElement.GetProperty("runs").EnumerateArray()){var expectedFile=NImageFile.Read(new StringReader(record.GetProperty("xml").GetString()!));var actualFile=NImageCalibrationExport.Build(new(new(frames,frames.Count,frames.Count),0,boards),solved,metrics,cameraMoves:record.GetProperty("cameraMoves").GetBoolean());Check(expectedFile.RotationDirection==actualFile.RotationDirection,"Original three-rotation file relation");Check(expectedFile.Handedness==actualFile.Handedness,"Original three-rotation file handedness");var fileMatrixDelta=expectedFile.Matrix.Zip(actualFile.Matrix).Select(p=>p.Second-p.First).ToArray();fileMatrixComparisons.Add(new{cameraMoves=record.GetProperty("cameraMoves").GetBoolean(),fileMatrixDelta,withinOriginalAbsolute1e4=fileMatrixDelta.All(d=>Math.Abs(d)<1e-4)});Check(actualFile.Matrix.Count==9&&fileMatrixDelta.All(d=>Math.Abs(d)<1e-4),"Original full module file matrix meets unchanged absolute 1e-4");Check(expectedFile.Matrix.Zip(actualFile.Matrix).All(p=>BitConverter.SingleToInt32Bits((float)p.First)==BitConverter.SingleToInt32Bits((float)p.Second)),"Original full module file matrix 9/9 float bits");Check(expectedFile.ImagePoints.Count==actualFile.ImagePoints.Count&&expectedFile.ImagePoints.Zip(actualFile.ImagePoints).All(p=>Math.Abs(p.First.X-p.Second.X)<1e-4&&Math.Abs(p.First.Y-p.Second.Y)<1e-4&&Math.Abs(p.First.R-p.Second.R)<1e-4),"Original full module image trajectory/angle");}}
   if(trans==9&&rot==0){var sdkMatrix=native.GetProperty("matrix").EnumerateArray().Select(p=>p.GetDouble()).ToArray();Check(sdkMatrix.Zip(solved.Matrix).All(p=>BitConverter.SingleToInt32Bits((float)p.First)==BitConverter.SingleToInt32Bits((float)p.Second)),"Original 9+0 SDK matrix 9/9 float bits");using var originEvidence=JsonDocument.Parse(File.ReadAllText("docs/plugins/n-image-translation-origin-evidence.json"));foreach(var record in originEvidence.RootElement.GetProperty("originalModuleFiles").EnumerateArray()){var expectedFile=NImageFile.Read(new StringReader(record.GetProperty("xml").GetString()!));var actualFile=NImageCalibrationExport.Build(new(new(frames,frames.Count,frames.Count),0,boards),solved,metrics,cameraMoves:record.GetProperty("cameraMoves").GetBoolean());var delta=expectedFile.Matrix.Zip(actualFile.Matrix).Select(p=>p.Second-p.First).ToArray();Check(delta.Length==9&&delta.All(d=>Math.Abs(d)<1e-4),"Original 9+0 file matrix unchanged absolute 1e-4");Check(expectedFile.Matrix.Zip(actualFile.Matrix).All(p=>BitConverter.SingleToInt32Bits((float)p.First)==BitConverter.SingleToInt32Bits((float)p.Second)),"Original 9+0 static/moving file matrix 9/9 float bits");Check(expectedFile.RotationDirection==actualFile.RotationDirection&&expectedFile.Handedness==actualFile.Handedness&&expectedFile.WorldPoints.SequenceEqual(actualFile.WorldPoints),"Original 9+0 static/moving relation, handedness and physical trajectory");Check(expectedFile.ImagePoints.Count==actualFile.ImagePoints.Count&&expectedFile.ImagePoints.Zip(actualFile.ImagePoints).All(p=>Math.Abs(p.First.X-p.Second.X)<1e-4&&Math.Abs(p.First.Y-p.Second.Y)<1e-4&&Math.Abs(p.First.R-p.Second.R)<1e-4),"Original 9+0 image trajectory/angle");translationOriginComparisons.Add(new{cameraMoves=record.GetProperty("cameraMoves").GetBoolean(),delta,floatBitMatches=expectedFile.Matrix.Zip(actualFile.Matrix).Count(p=>BitConverter.SingleToInt32Bits((float)p.First)==BitConverter.SingleToInt32Bits((float)p.Second))});}}
   var expected=new Dictionary<string,double>();var integers=new Dictionary<string,int>();
   void E(string group,string avg,string max,string worldAvg,string worldMax,string index){var row=native.GetProperty(group);expected[avg]=row[0].GetDouble();expected[max]=row[1].GetDouble();integers[index]=row[2].GetInt32();expected[worldAvg]=row[3].GetDouble();expected[worldMax]=row[4].GetDouble();}
   E("transError","TransError","TransEstMax","TransWorldError","TransErrWorldMax","TransErrMaxPtsNum");E("rotError","RotError","RotErrMax","RotWorldError","RotErrWorldMax","RotErrMaxPtsNum");
   for(int i=0;i<3;i++){string suffix=new[]{"Trans","Scale","Rotate"}[i];expected["TransMotionErrAvg"+suffix]=native.GetProperty("transMotionAverage")[i].GetDouble();expected["TransMotionErrMax"+suffix]=native.GetProperty("transMotionMaximum")[i].GetDouble();}
   expected["RotMotionErrAvg"]=native.GetProperty("rotMotion")[0].GetDouble();expected["RotMotionErrMax"]=native.GetProperty("rotMotion")[1].GetDouble();integers["RotMotionErrPicIndex"]=native.GetProperty("rotMotion")[2].GetInt32();integers["TransMotionErrPicIndex"]=native.GetProperty("transMotionIndex").GetInt32();integers["RotDirectState"]=native.GetProperty("direction").GetInt32();expected["RotateCenterPointX"]=native.GetProperty("center")[0].GetDouble();expected["RotateCenterPointY"]=native.GetProperty("center")[1].GetDouble();
   for(int i=0;i<5;i++)expected[new[]{"DirectionXVectorX","DirectionXVectorY","DirectionYVectorX","DirectionYVectorY","MoveDirec"}[i]]=native.GetProperty("vectors")[i].GetDouble();
   var differences=expected.ToDictionary(p=>p.Key,p=>Math.Abs(metrics.Numbers[p.Key]-p.Value));foreach(var p in differences)Check(p.Value<1e-4,$"{trans}+{rot} native {p.Key}: {p.Value}");foreach(var p in integers)Check(metrics.Integers[p.Key]==p.Value,$"{trans}+{rot} native {p.Key}: {metrics.Integers[p.Key]} expected {p.Value}");Check(metrics.Status==native.GetProperty("status").GetUInt32(),$"{trans}+{rot} native status: {metrics.Status:x}");reports.Add(new{trans,rot,differences,metrics});
  }
  Directory.CreateDirectory("analysis/full-audit/n-image-calibration/numerical-probe");File.WriteAllText("analysis/full-audit/n-image-calibration/numerical-probe/scalar-verification.json",JsonSerializer.Serialize(new{checks,failures,fileMatrixComparisons,translationOriginComparisons,reports},new JsonSerializerOptions{WriteIndented=true}));if(failures.Count>0)throw new Exception(string.Join("\n",failures));return checks;
 }
}
